import logging
from ute_ue.lteuepool import CfgFileBasedUePool
from ute_common_abstract_core.config import Config as CoreConfig
from taf.ue.plugin.mtk.config import Configuration, ConfigAdapter590

CONSTRUCTOR_PARAMETERS = 'CONSTRUCTOR_PARAMETERS'


class MediaTekUePool(CfgFileBasedUePool):
    """MediaTek Ue Pool"""
    def __init__(self, config_file_path=None, inline_config=None):
        """

        :param config_file_path: ute_ue yaml config file
        :param inline_config:  data structure read from ute_ue yaml config file
        """
        """Basic initialization."""
        if inline_config is None:
            inline_config = {}
        super(MediaTekUePool, self).__init__(config_file_path, inline_config)
        self.logger = logging.getLogger('ute_ue')

    def shutdown(self):
        self.logger.debug("Shutdown MediaTek ue pool in taken devices:{}".format(self._taken_devices))
        for ue_name in list(self._taken_devices):
            ue = self._return_device_to_available_devices(ue_name)
            ue.shutdown()

    def create_device(self, device_name, device_config):
        logging.info('Create device in MediaTekUePool start.')

        self._update_appserver_config(device_config)

        device_config, pdn_config = self._update_pdn_config(device_config)
        Configuration(ConfigAdapter590(pdn_config))
        device_config = self._update_capabilities_config(device_config)
        device = super(MediaTekUePool, self).create_device(device_name, device_config)
        logging.info('Created device in MediaTekUePool successfully.')
        return device

    def convert_pool_type_2_pool_class_fullname(self, pool_type):
        return "taf.ue.plugin.mtk.mtkuepool.MediaTekUePool"

    @classmethod
    def convert_device_type_2_device_class_fullname(cls, device_type):
        return "taf.ue.plugin.mtk.mtkue.MediaTekUe"

    def _update_pdn_config(self, device_config):
        demo_ue_pdn_config = {}
        pdn_config = CoreConfig().get_config(section='PDN')
        if pdn_config:
            ue_pool_name = self.__class__.__name__
            for pdn_name, pdn_cfg_per_ue_pool in pdn_config.items():
                demo_ue_pdn_config[pdn_name] = {'apn': pdn_cfg_per_ue_pool['apn']}  # apn is required key
                if ue_pool_name in pdn_cfg_per_ue_pool:
                    demo_ue_pdn_config[pdn_name].update(pdn_cfg_per_ue_pool[ue_pool_name])

        device_config['CONSTRUCTOR_PARAMETERS']['configuration']['PDN'] = demo_ue_pdn_config
        default_apn = device_config['CONSTRUCTOR_PARAMETERS']['configuration']["data_transfer"]["pdn_name"]
        if default_apn not in device_config['CONSTRUCTOR_PARAMETERS']['configuration']['PDN']:
            device_config['CONSTRUCTOR_PARAMETERS']['configuration']['PDN'][default_apn] = {"apn": default_apn,
                                                                                            "pdp_type": "IP"}
        demo_ue_pdn_config = device_config['CONSTRUCTOR_PARAMETERS']['configuration']['PDN']
        return device_config, demo_ue_pdn_config

    @staticmethod
    def _update_appserver_config(device_config):
        appserver_config = CoreConfig().get_config(section='APPSERVER')
        if appserver_config:
            device_config['CONSTRUCTOR_PARAMETERS']['configuration']['APPSERVER'] = appserver_config

    @staticmethod
    def _update_capabilities_config(device_config):
        device_config['CONSTRUCTOR_PARAMETERS']['configuration']['CAPABILITIES'] = \
            device_config['CAPABILITIES']
        return device_config
